// GFA VRCC — Grace Recovery OS
// Cloudflare Worker serving all four VRCC tools
// Deployed: 2026-07-18

function b64toHTML(b64) {
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return new TextDecoder('utf-8').decode(bytes);
}

const PAGES = {
  vrcc:         "",
  architecture: "",
  slogans:      "",
  enneagram:    "",
};

const ROUTES = {
  "/":               "vrcc",
  "/index.html":     "vrcc",
  "/architecture":   "architecture",
  "/architecture/":  "architecture",
  "/slogans":        "slogans",
  "/slogans/":       "slogans",
  "/enneagram":      "enneagram",
  "/enneagram/":     "enneagram",
};

const NAV_HTML = `
<!DOCTYPE html><html lang="en"><head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>GFA Recovery OS — Grace For Addictions</title>
<style>
  body{margin:0;background:#040410;color:#fff;font-family:'Segoe UI',sans-serif;display:flex;align-items:center;justify-content:center;min-height:100vh;}
  .hub{max-width:480px;padding:40px 20px;text-align:center;}
  h1{font-size:1.6rem;margin-bottom:6px;color:#1FB6B6;}
  p{color:rgba(255,255,255,.5);font-size:.9rem;margin-bottom:32px;}
  .grid{display:grid;gap:14px;}
  a{display:block;padding:18px 24px;border-radius:14px;border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.03);color:#fff;text-decoration:none;transition:all .2s;}
  a:hover{border-color:#1FB6B6;background:rgba(31,182,182,.08);}
  .label{font-size:.65rem;text-transform:uppercase;letter-spacing:.12em;color:#1FB6B6;margin-bottom:4px;}
  .title{font-size:1rem;font-weight:600;}
  .desc{font-size:.78rem;color:rgba(255,255,255,.45);margin-top:4px;}
</style></head><body>
<div class="hub">
  <h1>Grace Recovery OS</h1>
  <p>Grace For Addictions · Virtual Recovery Community Center</p>
  <div class="grid">
    <a href="/"><div class="label">Main Platform</div><div class="title">✦ VRCC — Recovery Among the Stars</div><div class="desc">Iowa's first Virtual Recovery Community Center · JUST GRACE 2026</div></a>
    <a href="/architecture"><div class="label">System Design</div><div class="title">⬡ Grace AI Architecture</div><div class="desc">GRACE Integration Blueprint · Power Trio Tech Stack</div></a>
    <a href="/slogans"><div class="label">Recovery Tools</div><div class="title">◈ Slogan Seed Viewer</div><div class="desc">GFA Recovery Slogan System · Recovering the Mind</div></a>
    <a href="/enneagram"><div class="label">Recovery Tools</div><div class="title">◉ Enneagram Recovery Map</div><div class="desc">Type-specific recovery pathways · GFA Framework</div></a>
  </div>
</div></body></html>`;

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const path = url.pathname;

    // Hub nav page
    if (path === "/hub" || path === "/hub/") {
      return new Response(NAV_HTML, {
        headers: { "Content-Type": "text/html;charset=UTF-8",
                   "Cache-Control": "public,max-age=3600",
                   "X-Powered-By": "GFA Recovery OS" }
      });
    }

    const pageKey = ROUTES[path];
    if (pageKey && PAGES[pageKey]) {
      const html = b64toHTML(PAGES[pageKey]);
      return new Response(html, {
        headers: {
          "Content-Type": "text/html;charset=UTF-8",
          "Cache-Control": "public,max-age=3600",
          "X-Frame-Options": "SAMEORIGIN",
          "X-Content-Type-Options": "nosniff",
          "Referrer-Policy": "strict-origin-when-cross-origin",
          "X-Powered-By": "GFA Recovery OS · graceforaddictions.org"
        }
      });
    }

    // 404
    return new Response(`<!DOCTYPE html><html><body style="background:#040410;color:#fff;font-family:sans-serif;text-align:center;padding:80px 20px">
      <h2 style="color:#1FB6B6">404</h2><p>Page not found.</p>
      <a href="/" style="color:#1FB6B6">← Back to VRCC</a>
    </body></html>`, { status: 404, headers: { "Content-Type": "text/html;charset=UTF-8" } });
  }
};
